-- Mavjud 6 ta darsni bazaga yuklash (bir marta ishga tushiriladi)
INSERT INTO schedules (lesson_number,topic,level,location,starts_at,duration_min,explanation,vocab,links,questions,created_at) VALUES (1,'1-Dars: Harflar, Raqamlar, Harflar birikmalari, Alifbo, So‘zlar, Tovushlar va Gapni tarjima qilish tartibi','A1 (Boshlang‘ich)','B-bino, 204-xona',1795076400000,80,'1. ALIFBO VA HARFLAR (26 TA HARF):
• Ingliz alifbosida 26 ta harf bor. Unli harflar: A, E, I, O, U (va ba’zan Y). Qolganlari undosh harflar.
• Harfning nomi va so‘z ichidagi tovushi har doim bir xil bo‘lavermaydi.

2. TOVUSHLAR VA HARFLAR BIRIKMALARI:
• SH -> /ʃ/ (ship, she, shop)
• CH -> /tʃ/ (chair, child) yoki /k/ (school, chemistry)
• PH -> /f/ (phone, photo)
• TH -> /θ/ (think, three) va /ð/ (this, that, the)
• CK -> /k/ (black, sock)

3. RAQAMLAR (1–100+):
• 1–12: one, two, three, four, five, six, seven, eight, nine, ten, eleven, twelve.
• 13–19 (-teen): thirteen, fourteen, fifteen, sixteen, seventeen, eighteen, nineteen.
• 20, 30, 40, 50...: twenty, thirty, forty (e’tibor bering: "u" harfi yo‘q!), fifty, one hundred.

4. SO‘ZLAR VA GAPNI TARJIMA QILISH TARTIBI:
• Inglizcha darak gapda asosiy tartib: EGA (Subject) + KESIM / FE’L (Verb) + TO‘LDIRUVCHI (Object) + JOY (Place) + VAQT (Time).
• Masalan: "Men har kuni maktabda ingliz tilini o‘rganaman." -> "I study English at school every day."','[]','[{"id":"lnk-l1-1","platform":"Telegram","title":"1-Dars: Alifbo, Raqamlar va Tarjima tartibi konspekti","url":"https://t.me/english_peers_club"}]','[{"id":1,"skill":"Alifbo va harflar","question":"Ingliz alifbosida jami nechta harf bor?","options":["24 ta","26 ta","28 ta","30 ta"],"correctIndex":1,"explanation":"Ingliz alifbosida 26 ta harf mavjud (5-6 ta unli va qolgani undosh harflar).","advice":"Alifbodagi barcha 26 ta harfning nomini va talaffuzini yod oling."},{"id":2,"skill":"Tovushlar va unlilar","question":"Ingliz tilida klassik unli harflar qaysilar?","options":["A, E, I, O, U (va ba’zan Y)","A, O, U, I, E, Ə","B, C, D, F, G","A, E, I, O, W"],"correctIndex":0,"explanation":"Asosiy unli harflar A, E, I, O, U bo‘lib, Y ko‘pincha unli tovush beradi.","advice":"Unli harflarning qisqa va cho‘ziq tovushlarini farqlashni mashq qiling."},{"id":3,"skill":"Harflar birikmalari","question":"\"SH\" harflar birikmasi odatda qanday tovush beradi?","options":["/ʃ/ (\"sh\")","/tʃ/ (\"ch\")","/s/ (\"s\")","/ʒ/ (\"j\")"],"correctIndex":0,"explanation":"\"SH\" birikmasi o‘zbekcha \"sh\" ga yaqin /ʃ/ tovushini beradi: ship, she, shop.","advice":"\"SH\" (/ʃ/) va \"CH\" (/tʃ/) birikmalarini adashtirmang."},{"id":4,"skill":"Harflar birikmalari","question":"\"CH\" harflar birikmasi qaysi so‘zda /tʃ/ (\"ch\") o‘qiladi?","options":["School","Chair","Chemistry","Character"],"correctIndex":1,"explanation":"\"Chair\" so‘zida CH -> /tʃ/ o‘qiladi. (School, chemistry, characterda CH -> /k/ o‘qiladi).","advice":"\"CH\" birikmasi ko‘pincha /tʃ/, lekin yunoncha so‘zlarda /k/ bo‘lishini esda tuting."},{"id":5,"skill":"Harflar birikmalari","question":"\"PH\" harflar birikmasi qaysi tovushni beradi?","options":["/f/ (\"f\")","/p/ (\"p\")","/h/ (\"h\")","/v/ (\"v\")"],"correctIndex":0,"explanation":"\"PH\" birikmasi phone, photo, elephant so‘zlarida /f/ tovushini beradi.","advice":"\"PH\" ko‘rsangiz, darhol /f/ tovushini eslang."},{"id":6,"skill":"Harflar birikmalari","question":"\"TH\" birikmasining ikki asosiy tovushi qaysilar?","options":["/θ/ va /ð/","/t/ va /d/","/s/ va /z/","/f/ va /v/"],"correctIndex":0,"explanation":"\"TH\" jarangsiz /θ/ (think, three) va jarangli /ð/ (this, that, the) tovushlarini beradi.","advice":"Til uchini old tishlar orasiga qo‘yib /θ/ va /ð/ tovushlarini mashq qiling."},{"id":7,"skill":"Raqamlar","question":"\"15\" soni inglizcha qanday yoziladi va aytiladi?","options":["Fifty","Fifteen","Fiveteen","Fiftin"],"correctIndex":1,"explanation":"15 — fifteen (/ˌfɪfˈtiːn/), 50 esa fifty (/ˈfɪfti/).","advice":"\"-teen\" (13–19) oxirgi bo‘g‘inga urg‘u beradi, \"-ty\" (20–90) birinchi bo‘g‘inga."},{"id":8,"skill":"Raqamlar","question":"\"40\" sonining to‘g‘ri imlosi qaysi?","options":["Fourty","Forty","Fourteen","Forti"],"correctIndex":1,"explanation":"40 har doim \"forty\" deb yoziladi (\"u\" harfi tushib qoladi!).","advice":"\"Four\" (4) da \"u\" bor, lekin \"forty\" (40) da \"u\" yo‘q — imloga e’tibor bering."},{"id":9,"skill":"Raqamlar","question":"\"12\" soni inglizcha qanday aytiladi?","options":["Twelf","Twelve","Twentieth","Two"],"correctIndex":1,"explanation":"12 — twelve (/twelv/).","advice":"1 dan 20 gacha bo‘lgan sonlarni yozma va og‘zaki pishiqlang."},{"id":10,"skill":"Raqamlar","question":"\"100\" raqami inglizcha qanday ifodalanadi?","options":["One hundred","One thousand","Ten hundred","A hundredth"],"correctIndex":0,"explanation":"100 — one hundred (yoki a hundred).","advice":"Yuzlik, minglik sonlarni tuzish qoidasini takrorlang."},{"id":11,"skill":"Tarjima tartibi","question":"Inglizcha darak gapda so‘z tartibi qanday bo‘ladi?","options":["Fe’l + Ega + To‘ldiruvchi","Ega + Kesim (Fe’l) + To‘ldiruvchi + Hol (Joy, Vaqt)","Hol + Kesim + Ega","To‘ldiruvchi + Ega + Fe’l"],"correctIndex":1,"explanation":"Ingliz tilida gap tartibi qat’iy: Subject (Ega) + Verb (Fe’l) + Object (To‘ldiruvchi) + Place + Time.","advice":"O‘zbekcha gapni tarjima qilayotganda avval EGA va FE’LNI toping."},{"id":12,"skill":"Tarjima tartibi","question":"\"Men har kuni kitob o‘qiyman\" gapining to‘g‘ri tartibi qaysi?","options":["Every day I book read.","I read a book every day.","Read I a book every day.","I a book read every day."],"correctIndex":1,"explanation":"Ega (I) + Fe’l (read) + To‘ldiruvchi (a book) + Vaqt holi (every day).","advice":"Vaqt holini (every day, tomorrow) odatda gap oxiriga qo‘ying."},{"id":13,"skill":"Tarjima tartibi","question":"Joy holi va vaqt holi bir gapda kelsa, qaysi tartibda turadi?","options":["Vaqt holi, keyin Joy holi","Joy holi, keyin Vaqt holi (Place before Time)","Ikkalasi ham fe’ldan oldin","Tartib ahamiyatsiz"],"correctIndex":0,"explanation":"Ingliz tilida odatda JOY holi VAQT holidan oldin keladi: \"at school\" (joy) + \"at 9 o’clock\" (vaqt).","advice":"Eslab qoling: Joy (Place) -> Vaqt (Time)."},{"id":14,"skill":"Alifbo va harflar","question":"\"Q\" harfidan keyin odatda qaysi harf keladi?","options":["U","A","O","E"],"correctIndex":0,"explanation":"Ingliz tilida \"Q\" harfi deyarli har doim \"U\" bilan birga keladi: queen, question, quick.","advice":"\"Q\" harfini ko‘rsangiz, ko‘pincha yonida \"U\" turadi."},{"id":15,"skill":"Tovushlar va unlilar","question":"\"C\" harfi \"E, I, Y\" harflaridan oldin qanday o‘qiladi?","options":["/s/ (\"s\") kabi","/k/ (\"k\") kabi","/tʃ/ (\"ch\") kabi","O‘qilmaydi"],"correctIndex":0,"explanation":"C + e/i/y -> /s/ (city, cent, cycle); C + a/o/u -> /k/ (cat, cup, coat).","advice":"\"C\" harfining yumshoq (/s/) va qattiq (/k/) o‘qilish qoidasini yodlang."},{"id":16,"skill":"Tovushlar va unlilar","question":"\"G\" harfi \"G + a/o/u\" holatida qanday o‘qiladi?","options":["/ɡ/ (\"g\") kabi","/dʒ/ (\"j\") kabi","/h/ (\"h\") kabi","O‘qilmaydi"],"correctIndex":0,"explanation":"\"Game, go, gun\" so‘zlarida G -> /ɡ/ o‘qiladi.","advice":"G + a/o/u ko‘pincha /ɡ/ tovushini beradi."},{"id":17,"skill":"Harflar birikmalari","question":"\"CK\" birikmasi qanday tovushni beradi?","options":["/k/ (\"k\")","/s/ (\"s\")","/tʃ/ (\"ch\")","/ʃ/ (\"sh\")"],"correctIndex":0,"explanation":"\"CK\" birikmasi qisqa unlidan keyin /k/ tovushini beradi: black, sock, clock.","advice":"\"CK\" birikmasi bitta aniq /k/ tovushi beradi."},{"id":18,"skill":"Harflar birikmalari","question":"\"NG\" birikmasi so‘z oxirida qanday talaffuz qilinadi?","options":["Burun orqali /ŋ/ (ming/rang oxiridagi tovushga yaqin)","Aniq /n/ + /ɡ/ + /ə/","/dʒ/ (\"j\")","/ʃ/ (\"sh\")"],"correctIndex":0,"explanation":"\"Sing, song, morning\" so‘zlarida NG -> /ŋ/ burun tovushi chiqaradi.","advice":"\"Sing\" so‘zida oxirida alohida \"g\" tovushini kuchaytirib yubormang."},{"id":19,"skill":"Raqamlar","question":"\"8\" raqami inglizcha qanday yoziladi?","options":["Eigth","Eight","Eigh","Aight"],"correctIndex":1,"explanation":"8 — eight (/eɪt/).","advice":"8 (eight) va 18 (eighteen) so‘zlarining imlosini mashq qiling."},{"id":20,"skill":"Raqamlar","question":"\"20\" raqami inglizcha qanday yoziladi?","options":["Twenty","Twinty","Twente","Twoenty"],"correctIndex":0,"explanation":"20 — twenty (/ˈtwenti/).","advice":"O‘nlik sonlarni (20, 30, 40, 50...) tartib bilan yozib ko‘ring."},{"id":21,"skill":"Tarjima tartibi","question":"\"U qiz maktabda ingliz tilini o‘rganadi\" gapida EGA qaysi?","options":["maktabda","ingliz tilini","U qiz (She)","o‘rganadi"],"correctIndex":2,"explanation":"Harakatni bajaruvchi shaxs — \"U qiz\" (She).","advice":"Har doim \"Kim? Nima?\" savoli bilan egani toping."},{"id":22,"skill":"Tarjima tartibi","question":"O‘zbek tilida kesim ko‘pincha gapning oxirida kelsa, ingliz tilida qayerda turadi?","options":["Oxirida","Egadan darhol keyin","Gap boshida","Ega bilan birga oxirida"],"correctIndex":1,"explanation":"Ingliz tilida kesim (fe’l) egadan darhol keyin qo‘yiladi.","advice":"O‘zbekchadagi \"oxirgi so‘zni\" inglizchada \"ikkinchi o‘ringa\" olib chiqing."},{"id":23,"skill":"Alifbo va harflar","question":"\"W\" harfi inglizcha qanday nomlanadi?","options":["Double-u","Vee","Double-v","O-w"],"correctIndex":0,"explanation":"\"W\" harfi \"double-u\" (qo‘sh U) deb aytiladi.","advice":"Alifbo harflarining inglizcha nomlarini takrorlang."},{"id":24,"skill":"Tovushlar va unlilar","question":"\"Y\" harfi \"yellow, yes, you\" so‘zlarida qanday tovush beradi?","options":["/j/ (\"y\")","/i/ (\"i\")","/dʒ/ (\"j\")","/w/ (\"w\")"],"correctIndex":0,"explanation":"So‘z boshida \"Y\" odatda /j/ (o‘zbekcha \"y\") tovushini beradi.","advice":"\"Y\" so‘z boshida kelsa /j/, so‘z oxirida kelsa ko‘pincha /i/ yoki /aɪ/ bo‘ladi."},{"id":25,"skill":"Harflar birikmalari","question":"\"SH\" birikmasi qaysi so‘zda bor?","options":["Fish","Dish","Wash","Barchasida"],"correctIndex":3,"explanation":"Fish, dish va wash so‘zlarining barchasida \"SH\" (/ʃ/) bor.","advice":"So‘z ichidagi va oxiridagi \"SH\" ni aniq talaffuz qiling."},{"id":26,"skill":"Raqamlar","question":"\"3\" raqami inglizcha qanday yoziladi?","options":["Tree","Three","Thre","Trey"],"correctIndex":1,"explanation":"3 — three (/θriː/). (\"Tree\" — daraxt degani!).","advice":"\"Three\" (3) ni \"th\" bilan, \"tree\" (daraxt) ni \"t\" bilan farqlang."},{"id":27,"skill":"Raqamlar","question":"\"11\" raqami inglizcha qanday aytiladi?","options":["Eleven","Eleventh","One-one","Telve"],"correctIndex":0,"explanation":"11 — eleven (/ɪˈlevn/).","advice":"11 dan 19 gacha bo‘lgan sonlarni alohida yodlang."},{"id":28,"skill":"Tarjima tartibi","question":"\"Biz bugun kechqurun uyda dars qilamiz\" gapida VAQT HOLI qaysi?","options":["uyda","dars qilamiz","bugun kechqurun (tonight)","Biz"],"correctIndex":2,"explanation":"\"Bugun kechqurun\" (tonight) — vaqt holi.","advice":"Gapdagi vaqt ifodalarini ajrata olish tarjimani osonlashtiradi."},{"id":29,"skill":"Tarjima tartibi","question":"\"Men olma yaxshi ko‘raman\" gapining to‘g‘ri inglizcha varianti qaysi?","options":["Apple I like.","I like apples.","Like I apples.","I apples like."],"correctIndex":1,"explanation":"Subject (I) + Verb (like) + Object (apples).","advice":"Ega -> Fe’l -> To‘ldiruvchi zanjirini mustahkamlang."},{"id":30,"skill":"Alifbo va harflar","question":"Nega ingliz tilida harf bilan tovush har doim ham 100% mos kelmaydi?","options":["Chunki 26 ta harf 40 dan ortiq tovushni ifodalaydi","Chunki alifbo noto‘g‘ri tuzilgan","Chunki unlilar yo‘q","Chunki faqat bosh harflar o‘qiladi"],"correctIndex":0,"explanation":"26 ta harf yordamida 44 ta atrofida tovush ifodalanadi, shuning uchun transkripsiya va harf birikmalari muhim.","advice":"Yangi so‘z o‘rganganda ham imlosini, ham talaffuzini tekshiring."}]',1795580034579);
INSERT INTO schedules (lesson_number,topic,level,location,starts_at,duration_min,explanation,vocab,links,questions,created_at) VALUES (2,'2-Dars: "To be" va "Was / Were" ni birgalikda to‘liq tushuntirish (namunaviy misollar bilan)','A1 – A2','B-bino, 204-xona',1795249200000,80,'1. HOZIRGI ZAMONDA "TO BE" (AM / IS / ARE):
• I -> am ("I am a student." / "I’m ready.")
• He, she, it -> is ("She is a teacher." / "It is cold.")
• We, you, they -> are ("We are friends." / "They are here.")

2. O‘TGAN ZAMONDA "WAS / WERE":
• I, he, she, it -> was ("I was at home yesterday." / "He was tired.")
• We, you, they -> were ("We were happy." / "They were at school.")

3. INKOR VA SO‘ROQ SHAKLLARI:
• Inkor: to be + not -> am not (I’m not), is not (isn’t), are not (aren’t), was not (wasn’t), were not (weren’t).
• So‘roq: Am / Is / Are / Was / Were + EGA + ...?
  Masalan: "Are you ready?" / "Were they at the club yesterday?"

4. NAMUNAVIY TAQQOSLASH MISOLLARI:
• Hozir: "Today I am busy." -> O‘tgan: "Yesterday I was busy."
• Hozir: "They are in Samarkand." -> O‘tgan: "Last week they were in Samarkand."','[]','[{"id":"lnk-l2-1","platform":"Telegram","title":"2-Dars: To be & Was/Were jadvali va mashqlar","url":"https://t.me/english_peers_club"}]','[{"id":1,"skill":"To Be (Hozirgi zamon)","question":"\"I ___ a first-year student.\" Bo‘sh o‘ringa nima qo‘yiladi?","options":["am","is","are","were"],"correctIndex":0,"explanation":"\"I\" olmoshidan keyin hozirgi zamonda \"am\" ishlatiladi.","advice":"\"I\" -> har doim \"am\" (yoki o‘tmishda \"was\")."},{"id":2,"skill":"To Be (Hozirgi zamon)","question":"\"She ___ very kind and helpful.\"","options":["am","is","are","were"],"correctIndex":1,"explanation":"\"She\" (birlik, 3-shaxs) bilan hozirgi zamonda \"is\" qo‘llanadi.","advice":"He, she, it -> is."},{"id":3,"skill":"To Be (Hozirgi zamon)","question":"\"They ___ in the classroom now.\"","options":["am","is","are","was"],"correctIndex":2,"explanation":"\"They\" (ko‘plik) bilan hozirgi zamonda \"are\" ishlatiladi.","advice":"We, you, they -> are."},{"id":4,"skill":"Was / Were (O‘tgan zamon)","question":"\"Yesterday, I ___ at home all day.\"","options":["am","is","was","were"],"correctIndex":2,"explanation":"\"Yesterday\" o‘tgan zamonni bildiradi; \"I\" uchun o‘tgan zamon shakli \"was\".","advice":"O‘tgan zamon signal so‘zlariga (yesterday, last week, ago) e’tibor bering."},{"id":5,"skill":"Was / Were (O‘tgan zamon)","question":"\"We ___ very happy after the lesson yesterday.\"","options":["was","were","are","am"],"correctIndex":1,"explanation":"\"We\" (ko‘plik) va \"yesterday\" (o‘tgan zamon) -> \"were\".","advice":"We, you, they (o‘tgan zamon) -> were."},{"id":6,"skill":"Was / Were (O‘tgan zamon)","question":"\"He ___ tired last night.\"","options":["was","were","is","am"],"correctIndex":0,"explanation":"\"He\" va \"last night\" (o‘tgan zamon) -> \"was\".","advice":"I, he, she, it (o‘tgan zamon) -> was."},{"id":7,"skill":"Inkor va So‘roq","question":"\"They ___ not late for the meeting.\" To‘g‘ri shaklni toping:","options":["is","are","was","am"],"correctIndex":1,"explanation":"Ko‘plikdagi \"They\" bilan hozirgi zamonda \"are not\" (aren’t) ishlatiladi.","advice":"Inkor gapda \"not\" to be shaklidan keyin qo‘yiladi."},{"id":8,"skill":"Inkor va So‘roq","question":"\"___ you ready for the speaking club?\"","options":["Is","Am","Are","Was"],"correctIndex":2,"explanation":"\"You\" bilan hozirgi zamon so‘roq gapida \"Are\" gap boshiga chiqadi.","advice":"So‘roq gapda to be (am/is/are/was/were) egadan oldinga o‘tadi."},{"id":9,"skill":"Inkor va So‘roq","question":"\"___ she at the library two hours ago?\"","options":["Is","Are","Was","Were"],"correctIndex":2,"explanation":"\"Two hours ago\" o‘tgan zamon; \"she\" uchun so‘roq boshida \"Was\" keladi.","advice":"O‘tgan zamon so‘roq gaplarida \"Was\" yoki \"Were\" ni tanlang."},{"id":10,"skill":"Inkor va So‘roq","question":"\"It ___ cold last winter.\" (Inkor gap)","options":["wasn’t","weren’t","aren’t","isn’t"],"correctIndex":0,"explanation":"\"It\" va \"last winter\" -> o‘tgan zamon inkori \"wasn’t\" (was not).","advice":"Qisqa inkor shakllarni (isn’t, aren’t, wasn’t, weren’t) mashq qiling."},{"id":11,"skill":"To Be (Hozirgi zamon)","question":"\"My friends and I ___ ready to start.\"","options":["am","is","are","was"],"correctIndex":2,"explanation":"\"My friends and I\" = \"We\" (biz), shuning uchun \"are\".","advice":"Qo‘shma egani (\"... and I\") \"we\" ga almashtirib tekshiring."},{"id":12,"skill":"Was / Were (O‘tgan zamon)","question":"\"The weather ___ sunny yesterday.\"","options":["was","were","is","are"],"correctIndex":0,"explanation":"\"The weather\" = \"It\" (birlik), \"yesterday\" -> \"was\".","advice":"Ob-havo, vaqt, masofa gaplarida ega \"it\" bo‘ladi."},{"id":13,"skill":"Was / Were (O‘tgan zamon)","question":"\"The students ___ active in the last session.\"","options":["was","were","is","am"],"correctIndex":1,"explanation":"\"The students\" — ko‘plik, \"last session\" — o‘tgan zamon -> \"were\".","advice":"Ko‘plikdagi otlarga \"were\" qo‘llang."},{"id":14,"skill":"To Be (Hozirgi zamon)","question":"\"This book ___ very interesting.\"","options":["am","is","are","were"],"correctIndex":1,"explanation":"\"This book\" — birlik -> \"is\".","advice":"Birlikdagi otlar bilan \"is\" (hozirgi) yoki \"was\" (o‘tgan)."},{"id":15,"skill":"To Be (Hozirgi zamon)","question":"\"Those books ___ on my desk.\"","options":["am","is","are","was"],"correctIndex":2,"explanation":"\"Those books\" — ko‘plik -> \"are\".","advice":"Ko‘plikdagi otlar bilan \"are\" (hozirgi) yoki \"were\" (o‘tgan)."},{"id":16,"skill":"Inkor va So‘roq","question":"\"Where ___ you born?\"","options":["was","were","is","am"],"correctIndex":1,"explanation":"\"You\" bilan tug‘ilgan joy haqida so‘raganda \"Where were you born?\" deyiladi.","advice":"Tayyor savol qoliplarini yodlab oling."},{"id":17,"skill":"Inkor va So‘roq","question":"\"Who ___ your first English teacher?\"","options":["was","were","are","am"],"correctIndex":0,"explanation":"\"Your first English teacher\" birlikda -> \"was\".","advice":"Savol so‘zidan (Who, Where, Why) keyin to be keladi."},{"id":18,"skill":"To Be (Hozirgi zamon)","question":"\"I ___ not angry with you.\"","options":["am","is","are","were"],"correctIndex":0,"explanation":"\"I am not...\" — \"I’m not\" ham to‘g‘ri.","advice":"\"Am not\" qisqartirilganda \"I’m not\" bo‘ladi (\"amn’t\" noto‘g‘ri!)."},{"id":19,"skill":"Was / Were (O‘tgan zamon)","question":"\"___ they at home last Sunday?\"","options":["Was","Were","Are","Is"],"correctIndex":1,"explanation":"\"They\" va \"last Sunday\" -> \"Were\".","advice":"So‘roq gapda zamon va shaxs mosligini tekshiring."},{"id":20,"skill":"To Be (Hozirgi zamon)","question":"\"Samarkand ___ a historic city.\"","options":["am","is","are","were"],"correctIndex":1,"explanation":"Shahar nomi (birlik) va umumiy fakt -> \"is\".","advice":"Doimiy faktlar uchun hozirgi zamon (\"is\") ishlatiladi."},{"id":21,"skill":"Was / Were (O‘tgan zamon)","question":"\"When I was young, I ___ afraid of speaking English.\"","options":["am","is","was","were"],"correctIndex":2,"explanation":"\"When I was young...\" o‘tgan zamon hikoyasi -> \"was\".","advice":"Bitta gap ichida zamonlar mantiqiy mos kelishi kerak."},{"id":22,"skill":"Inkor va So‘roq","question":"\"No, they ___ not at the club yesterday.\"","options":["was","were","is","am"],"correctIndex":1,"explanation":"\"They\" + \"yesterday\" + inkor -> \"were not\" (weren’t).","advice":"Javobdagi \"No\" ko‘pincha inkor shaklni talab qiladi."},{"id":23,"skill":"To Be (Hozirgi zamon)","question":"\"You ___ my best peer friend.\"","options":["am","is","are","was"],"correctIndex":2,"explanation":"\"You\" bilan hozirgi zamonda har doim \"are\" ishlatiladi.","advice":"\"You\" olmoshiga har doim \"are\" (hozirgi) va \"were\" (o‘tgan) qo‘llang."},{"id":24,"skill":"To Be (Hozirgi zamon)","question":"Qaysi gap grammatik jihatdan TO‘G‘RI?","options":["She are a teacher.","They is students.","He is a good speaker.","I is ready."],"correctIndex":2,"explanation":"\"He is a good speaker.\" — to‘g‘ri tuzilgan gap.","advice":"Har bir shaxsga mos to be shaklini adashtirmang."},{"id":25,"skill":"Was / Were (O‘tgan zamon)","question":"Qaysi gap O‘TGAN ZAMONDA to‘g‘ri tuzilgan?","options":["We was at school yesterday.","We were at school yesterday.","We are at school yesterday.","We is at school yesterday."],"correctIndex":1,"explanation":"\"We were at school yesterday.\" — to‘g‘ri.","advice":"We + were + yesterday."},{"id":26,"skill":"Inkor va So‘roq","question":"\"Is he at home?\" savoliga qisqa tasdiq javob qaysi?","options":["Yes, he is.","Yes, he’s.","Yes, he are.","Yes, he was."],"correctIndex":0,"explanation":"Qisqa tasdiq javobda qisqartma (\"he’s\") ishlatilmaydi: \"Yes, he is.\"","advice":"Qisqa tasdiq javobda \"Yes, + olmosh + am/is/are/was/were\" shaklida yozing."},{"id":27,"skill":"Inkor va So‘roq","question":"\"Were they tired?\" savoliga qisqa inkor javob qaysi?","options":["No, they wasn’t.","No, they weren’t.","No, they aren’t.","No, they don’t."],"correctIndex":1,"explanation":"\"No, they weren’t.\" (yoki \"No, they were not.\")","advice":"Qisqa inkor javobda \"No, + olmosh + isn’t/aren’t/wasn’t/weren’t\" ishlatiladi."},{"id":28,"skill":"To Be (Hozirgi zamon)","question":"\"My bag and my notebook ___ on the table.\"","options":["is","are","was","am"],"correctIndex":1,"explanation":"Ikki narsa (\"bag and notebook\") = ko‘plik -> \"are\".","advice":"Bir nechta narsa sanalsa, ko‘plik shakli (\"are\") ishlatiladi."},{"id":29,"skill":"Was / Were (O‘tgan zamon)","question":"\"Why ___ you absent yesterday?\"","options":["was","were","is","do"],"correctIndex":1,"explanation":"\"You\" uchun o‘tgan zamonda \"were\" ishlatiladi.","advice":"\"Why were you...?\" — foydali savol qolipi."},{"id":30,"skill":"To Be / Was-Were","question":"To be fe’li o‘zbek tiliga qanday tarjima qilinadi?","options":["Hozirgi zamonda ko‘pincha tushirib qoldiriladi (\"-dir\"/mavjud), o‘tgan zamonda \"edi/bo‘lgan edi\"","Faqat \"bormoq\" deb","Faqat \"qilmoq\" deb","Tarjima qilinmaydi"],"correctIndex":0,"explanation":"O‘zbek tilida \"Men talabaman\" deb aytiladi (\"man\" so‘zi shart emas), lekin inglizchada \"I am a student\" shart!","advice":"Inglizcha gapda to be ni tushirib qoldirmang."}]',1795580034580);
INSERT INTO schedules (lesson_number,topic,level,location,starts_at,duration_min,explanation,vocab,links,questions,created_at) VALUES (3,'3-Mavzu: Present Simple (Oddiy hozirgi zamon)','A1 – A2','B-bino, 204-xona',1795508400000,80,'1. PRESENT SIMPLE QACHON ISHLATILADI?
• Kundalik odatlar va muntazam harakatlar: "I wake up at 7 AM every day."
• Umumiy haqiqatlar va ilmiy faktlar: "The sun rises in the east."
• Dars jadvali va qatnov vaqtlari: "The class starts at 13:20."

2. DARAK GAP VA 3-SHAKS BIRLIK (-S / -ES / -IES):
• I, we, you, they + V1: "We speak English in our club."
• He, she, it + V1 + s/es/ies:
  - "She works" (+s)
  - "He goes / watches / washes" (-o, -ch, -sh, -ss, -x -> +es)
  - "She studies" (undosh + y -> +ies), "He plays" (unli + y -> +s)

3. INKOR VA SO‘ROQ (DO / DOES):
• Inkor: I/we/you/they + don’t + V1; he/she/it + doesn’t + V1 (fe’lda -s qolmaydi!).
• So‘roq: Do + I/we/you/they + V1...? | Does + he/she/it + V1...?

4. SIGNAL SO‘ZLAR:
• always, usually, often, sometimes, never, every day/week/month, once/twice a week.','[]','[{"id":"lnk-l3-1","platform":"YouTube","title":"3-Mavzu: Present Simple qoidalari va misollar","url":"https://www.youtube.com/results?search_query=present+simple+tense+examples"}]','[{"id":1,"skill":"3-shaxs (-s / -es)","question":"\"She ___ English every evening.\"","options":["study","studies","studying","studied"],"correctIndex":1,"explanation":"She (3-shaxs birlik) + undosh + Y -> \"ies\": studies.","advice":"Unli+Y -> -s (plays); undosh+Y -> -ies (studies)."},{"id":2,"skill":"3-shaxs (-s / -es)","question":"\"He ___ to work at 8 AM.\"","options":["go","goes","going","went"],"correctIndex":1,"explanation":"\"Go\" fe’li -o bilan tugagani uchun 3-shaxsda \"-es\" oladi: goes.","advice":"Oxiri -o, -ch, -sh, -ss, -x bilan tugasa \"-es\" qo‘shiladi."},{"id":3,"skill":"Signal so‘zlar","question":"\"I ___ drink coffee in the morning.\" (100% odat)","options":["always","never","rarely","hardly ever"],"correctIndex":0,"explanation":"\"Always\" (har doim) doimiy odatni bildiradi.","advice":"Always, usually, often, sometimes, never — Present Simple kalit so‘zlari."},{"id":4,"skill":"Do / Does (Inkor)","question":"\"They ___ live in Tashkent.\"","options":["don’t","doesn’t","isn’t","aren’t"],"correctIndex":0,"explanation":"Ko‘plikdagi \"They\" bilan inkor uchun \"don’t\" (do not) ishlatiladi.","advice":"I, we, you, they -> don’t."},{"id":5,"skill":"Do / Does (Inkor)","question":"\"He ___ like fast food.\"","options":["don’t","doesn’t","isn’t","aren’t"],"correctIndex":1,"explanation":"\"He\" bilan inkor uchun \"doesn’t\" ishlatiladi, asosiy fe’l esa \"-s\" siz yoziladi.","advice":"Doesn’t dan keyin fe’lga \"-s\" qo‘shmang: \"doesn’t like\" (likes emas!)."},{"id":6,"skill":"Do / Does (So‘roq)","question":"\"___ you speak Uzbek and English?\"","options":["Do","Does","Are","Is"],"correctIndex":0,"explanation":"\"You\" bilan oddiy fe’l savolida \"Do\" ishlatiladi.","advice":"Oddiy fe’llarda (speak, go, work) savol yasash uchun \"Do/Does\" kerak."},{"id":7,"skill":"Do / Does (So‘roq)","question":"\"___ your brother play chess?\"","options":["Do","Does","Is","Are"],"correctIndex":1,"explanation":"\"Your brother\" = \"He\" -> so‘roqda \"Does\" keladi.","advice":"Does + ega + V1 (asosiy shakldagi fe’l)."},{"id":8,"skill":"3-shaxs (-s / -es)","question":"\"The sun ___ in the east.\"","options":["rise","rises","rising","rose"],"correctIndex":1,"explanation":"Tabiat qonuni / umumiy haqiqat -> Present Simple; \"the sun\" birlik -> rises.","advice":"Ilmiy faktlar va tabiat hodisalari Present Simple da ifodalanadi."},{"id":9,"skill":"Signal so‘zlar","question":"Chastota ravishlari (always, usually, often) odatda gapda qayerda turadi?","options":["Asosiy fe’ldan oldin (lekin to be dan keyin)","Faqat gap oxirida","Faqat gap boshida","Artikldan oldin"],"correctIndex":0,"explanation":"\"I always wake up early.\" / \"She is always happy.\"","advice":"Fe’ldan oldin, to be (am/is/are) dan keyin qo‘ying."},{"id":10,"skill":"Do / Does (Inkor)","question":"\"My sister ___ watch TV on weekdays.\"","options":["don’t","doesn’t","not","no"],"correctIndex":1,"explanation":"\"My sister\" = \"She\" -> \"doesn’t watch\".","advice":"3-shaxs birlik inkorida \"doesn’t\" ishlatiladi."},{"id":11,"skill":"3-shaxs (-s / -es)","question":"\"She ___ her teeth twice a day.\"","options":["brush","brushes","brushs","brushing"],"correctIndex":1,"explanation":"\"Brush\" -sh bilan tugagani uchun \"-es\" oladi: brushes.","advice":"-sh oxiriga -es qo‘shing."},{"id":12,"skill":"Do / Does (So‘roq)","question":"\"What time ___ the train leave?\"","options":["do","does","is","are"],"correctIndex":1,"explanation":"\"The train\" birlikda -> \"does the train leave\".","advice":"Jadval va qatnov vaqtlari Present Simple bilan aytiladi."},{"id":13,"skill":"Signal so‘zlar","question":"\"She is ___ late for class!\" (Hech qachon kechikmaydi -> 0%)","options":["always","never","often","usually"],"correctIndex":1,"explanation":"\"Never\" inkor ma’noni beradi, shuning uchun gapda qo‘shimcha \"not\" ishlatilmaydi.","advice":"\"Never\" bor gapda ikki karra inkor qilmang."},{"id":14,"skill":"3-shaxs (-s / -es)","question":"\"He ___ English grammar very well.\"","options":["teach","teaches","teachs","teaching"],"correctIndex":1,"explanation":"\"Teach\" -ch bilan tugagani uchun \"-es\" qo‘shiladi: teaches.","advice":"-ch bilan tugagan fe’llarga -es qo‘shing."},{"id":15,"skill":"Do / Does (So‘roq)","question":"\"Where ___ your parents live?\"","options":["do","does","are","is"],"correctIndex":0,"explanation":"\"Your parents\" ko‘plikda -> \"do your parents live\".","advice":"Ko‘plikdagi otlar bilan \"do\" ishlatiladi."},{"id":16,"skill":"3-shaxs (-s / -es)","question":"\"It ___ a lot in autumn.\"","options":["rain","rains","raining","rained"],"correctIndex":1,"explanation":"\"It\" (3-shaxs birlik) -> rains.","advice":"It + fe’l + s."},{"id":17,"skill":"Do / Does (Inkor)","question":"\"We ___ go to the cinema every week.\"","options":["don’t","doesn’t","aren’t","wasn’t"],"correctIndex":0,"explanation":"\"We\" + \"don’t go\".","advice":"We don’t + V1."},{"id":18,"skill":"Signal so‘zlar","question":"\"I visit my grandparents ___ a month.\"","options":["once","one","first","one time"],"correctIndex":0,"explanation":"\"Bir marta\" inglizcha \"once\" (ikki marta — twice).","advice":"Once a week / twice a month — foydali iboralar."},{"id":19,"skill":"3-shaxs (-s / -es)","question":"\"Tom ___ his homework after dinner.\"","options":["do","does","dos","doing"],"correctIndex":1,"explanation":"\"Do\" fe’lining 3-shaxs shakli — \"does\".","advice":"Do -> does."},{"id":20,"skill":"Do / Does (So‘roq)","question":"\"___ they understand the rule?\"","options":["Do","Does","Are","Am"],"correctIndex":0,"explanation":"\"They\" + oddiy fe’l -> \"Do they understand\".","advice":"Understand holat fe’li Present Simple da ishlatiladi."},{"id":21,"skill":"3-shaxs (-s / -es)","question":"\"She ___ to music while walking.\"","options":["listen","listens","listening","listened"],"correctIndex":1,"explanation":"\"She listens...\" — oddiy -s qo‘shiladi.","advice":"Listen /ˈlɪsn/ da \"t\" o‘qilmasligini ham eslang!"},{"id":22,"skill":"Do / Does (Inkor)","question":"\"He ___ have any questions.\"","options":["don’t","doesn’t","hasn’t","haven’t"],"correctIndex":1,"explanation":"Present Simple inkorida \"doesn’t have\" ishlatiladi.","advice":"\"Doesn’t has\" emas, \"doesn’t have\" to‘g‘ri!"},{"id":23,"skill":"Signal so‘zlar","question":"\"On Saturdays, we ___ play football in the yard.\"","options":["usually","now","yesterday","tomorrow"],"correctIndex":0,"explanation":"\"On Saturdays\" muntazam odatni bildiradi -> \"usually\".","advice":"Hafta kunlari ko‘plikda (\"On Saturdays\") odatni bildiradi."},{"id":24,"skill":"3-shaxs (-s / -es)","question":"\"Water ___ at 100 degrees Celsius.\"","options":["boil","boils","boiling","boiled"],"correctIndex":1,"explanation":"Ilmiy haqiqat -> Present Simple; \"water\" sanalmaydi (birlik kabi) -> boils.","advice":"Umumiy haqiqatlar uchun Present Simple ishlating."},{"id":25,"skill":"Do / Does (So‘roq)","question":"\"How often ___ you practice speaking?\"","options":["do","does","are","have"],"correctIndex":0,"explanation":"\"How often do you...?\" — qanchalik tez-tez?","advice":"\"How often...?\" savoliga chastota ravishi bilan javob bering."},{"id":26,"skill":"3-shaxs (-s / -es)","question":"\"A pilot ___ airplanes.\"","options":["fly","flies","flys","flying"],"correctIndex":1,"explanation":"Undosh (l) + y -> \"flies\".","advice":"Fly -> flies."},{"id":27,"skill":"Do / Does (Inkor)","question":"\"I ___ eat spicy food.\"","options":["don’t","doesn’t","am not","wasn’t"],"correctIndex":0,"explanation":"\"I don’t eat...\"","advice":"I + don’t + V1."},{"id":28,"skill":"Signal so‘zlar","question":"Qaysi gap Present Simple uchun TO‘G‘RI?","options":["She is liking tea.","She likes tea every morning.","She like tea.","Does she likes tea?"],"correctIndex":1,"explanation":"\"She likes tea every morning.\" — to‘g‘ri.","advice":"Likeni ko‘pincha -ing siz Present Simple da ishlating."},{"id":29,"skill":"Do / Does (So‘roq)","question":"\"Does she know the answer?\" savoliga qisqa javob:","options":["Yes, she does.","Yes, she is.","Yes, she do.","Yes, does she."],"correctIndex":0,"explanation":"Savol \"Does\" bilan boshlansa, javob ham \"does/doesn’t\" bilan tugaydi.","advice":"Savoldagi yordamchi fe’lga mos javob bering."},{"id":30,"skill":"Umumiy Present Simple","question":"Present Simple qachon ishlatilmaydi?","options":["Kundalik odatlarda","Umumiy haqiqatlarda","Aynan hozir ko‘z oldingizda davom etayotgan harakatda (hozir yomg‘ir yog‘yapti)","Dars jadvali haqida gapirganda"],"correctIndex":2,"explanation":"Aynan hozir sodir bo‘layotgan ish uchun Present Continuous (\"is raining now\") ishlatiladi.","advice":"Odat/fakt -> Present Simple; aynan hozir -> Present Continuous."}]',1795580034580);
INSERT INTO schedules (lesson_number,topic,level,location,starts_at,duration_min,explanation,vocab,links,questions,created_at) VALUES (4,'4-Mavzu: There is / There are (Mavjudlik va joylashuv ifodasi)','A1 – A2','B-bino, 204-xona',1795681200000,80,'1. ASOSIY QOIDA:
• Biror joyda biror narsa/shaxs BORLIGINI aytishda "There is / There are" ishlatiladi.
• Tarjimada ko‘pincha oxiridan ("...da ... bor") o‘giriladi:
  "There is a book on the table." -> Stol ustida kitob bor.

2. HOZIRGI ZAMON (THERE IS / THERE ARE):
• Birlik va sanalmaydigan otlar: "There is a pen..." / "There is some water..."
• Ko‘plik otlar: "There are three students..." / "There are many books..."

3. O‘TGAN ZAMON (THERE WAS / THERE WERE):
• Birlik / sanalmaydigan: "There was a meeting yesterday."
• Ko‘plik: "There were many people at the event."

4. INKOR VA SO‘ROQ:
• Inkor: There isn’t / There aren’t / There wasn’t / There weren’t (yoki "There is no...").
• So‘roq: Is there...? / Are there...? / Was there...? / Were there...?','[]','[]','[{"id":1,"skill":"There is (Birlik)","question":"\"___ a new student in our group.\"","options":["There is","There are","There were","Are there"],"correctIndex":0,"explanation":"\"A new student\" birlikda -> \"There is\".","advice":"Birlikdagi sanaladigan ot oldidan \"There is a/an...\" ishlatiladi."},{"id":2,"skill":"There are (Ko‘plik)","question":"\"___ many books on the shelf.\"","options":["There is","There are","There was","Is there"],"correctIndex":1,"explanation":"\"Many books\" ko‘plikda -> \"There are\".","advice":"Ko‘plikdagi otlar oldidan \"There are...\" qo‘llang."},{"id":3,"skill":"Inkor shakli","question":"\"There ___ any water in the bottle.\"","options":["isn’t","aren’t","weren’t","are"],"correctIndex":0,"explanation":"\"Water\" sanalmaydigan ot (birlik kabi) -> \"There isn’t\".","advice":"Sanalmaydigan otlar bilan \"There is / isn’t\" ishlatiladi."},{"id":4,"skill":"Inkor shakli","question":"\"There ___ any chairs in this room.\"","options":["isn’t","aren’t","is","was"],"correctIndex":1,"explanation":"\"Chairs\" ko‘plikda -> \"There aren’t\".","advice":"Ko‘plik inkorida ko‘pincha \"any\" ishlatiladi: \"aren’t any\"."},{"id":5,"skill":"So‘roq shakli","question":"\"___ a park near your university?\"","options":["Is there","Are there","There is","There are"],"correctIndex":0,"explanation":"\"A park\" birlikda -> so‘roq \"Is there...?\"","advice":"Savolda \"is/are\" gap boshiga chiqadi."},{"id":6,"skill":"So‘roq shakli","question":"\"___ any students in the hall?\"","options":["Is there","Are there","There are","There is"],"correctIndex":1,"explanation":"\"Students\" ko‘plikda -> so‘roq \"Are there...?\"","advice":"Ko‘plik savolida \"Are there any...?\" ishlatiladi."},{"id":7,"skill":"O‘tgan zamon (There was / were)","question":"\"Yesterday, ___ a big concert in the city.\"","options":["there is","there are","there was","there were"],"correctIndex":2,"explanation":"\"Yesterday\" + \"a big concert\" (birlik) -> \"there was\".","advice":"O‘tgan zamon birlik -> there was."},{"id":8,"skill":"O‘tgan zamon (There was / were)","question":"\"Last week, ___ ten participants in the club.\"","options":["there is","there are","there was","there were"],"correctIndex":3,"explanation":"\"Last week\" + \"ten participants\" (ko‘plik) -> \"there were\".","advice":"O‘tgan zamon ko‘plik -> there were."},{"id":9,"skill":"Tarjima ma’nosi","question":"\"There is a pen on the table\" o‘zbek tiliga qanday tarjima qilinadi?","options":["Stol ustida ruchka bor.","Ruchka stol ustida.","Men ruchkani ko‘ryapman.","Stol ruchka ustida."],"correctIndex":0,"explanation":"\"There is/are\" ko‘pincha \"bor / mavjud\" ma’nosini beradi.","advice":"Yangilik sifatida biror narsa qayerda borligini aytishda \"There is/are\" ishlating."},{"id":10,"skill":"There is vs It is","question":"Qaysi gap TO‘G‘RI?","options":["There is a good book.","There is a good book on the desk.","There are a good book.","Is there a book are good?"],"correctIndex":1,"explanation":"\"There is + narsa + joy\" tuzilmasi tabiiy va to‘g‘ri.","advice":"Joy yoki mavjudlikni ko‘rsatishda \"There is/are\" ni to‘g‘ri qo‘llang."},{"id":11,"skill":"There is (Birlik)","question":"\"___ an apple in my bag.\"","options":["There is","There are","There were","Are there"],"correctIndex":0,"explanation":"\"An apple\" birlikda -> \"There is\".","advice":"Unli tovush oldidan \"an\" ishlatiladi."},{"id":12,"skill":"There are (Ko‘plik)","question":"\"___ two windows in the classroom.\"","options":["There is","There are","There was","Is there"],"correctIndex":1,"explanation":"\"Two windows\" ko‘plik -> \"There are\".","advice":"Soni 2 va undan ko‘p bo‘lsa — \"There are\"."},{"id":13,"skill":"Inkor shakli","question":"\"There ___ no milk left in the fridge.\"","options":["is","are","were","aren’t"],"correctIndex":0,"explanation":"\"No milk\" allaqachon inkor ma’nosini beradi, fe’l ijobiy shaklda (\"is\") turadi.","advice":"\"No\" ishlatilsa, fe’lni inkor qilmang (\"There is no...\")."},{"id":14,"skill":"So‘roq shakli","question":"\"Is there a bank near here?\" — \"Yes, ___.\"","options":["there is","it is","there are","is there"],"correctIndex":0,"explanation":"\"Is there...?\" savoliga \"Yes, there is.\" yoki \"No, there isn’t.\" deb javob beriladi.","advice":"Savolda \"there\" bo‘lsa, javobda ham \"there\" qaytadi."},{"id":15,"skill":"So‘roq shakli","question":"\"Are there any questions?\" — \"No, ___.\"","options":["there aren’t","there isn’t","they aren’t","there don’t"],"correctIndex":0,"explanation":"\"Questions\" ko‘plik -> \"No, there aren’t.\"","advice":"Ko‘plik savoliga \"there aren’t\" bilan javob bering."},{"id":16,"skill":"O‘tgan zamon (There was / were)","question":"\"___ any mistakes in your test yesterday?\"","options":["Was there","Were there","Is there","Are there"],"correctIndex":1,"explanation":"\"Mistakes\" ko‘plik + \"yesterday\" -> \"Were there\".","advice":"O‘tgan zamon ko‘plik so‘roq -> Were there."},{"id":17,"skill":"O‘tgan zamon (There was / were)","question":"\"There ___ a lot of snow last winter.\"","options":["was","were","are","is"],"correctIndex":0,"explanation":"\"Snow\" sanalmaydigan ot + \"last winter\" -> \"was\".","advice":"Sanalmaydigan ot o‘tgan zamonda \"was\" oladi."},{"id":18,"skill":"There is vs It is","question":"\"It’s raining outside\" va \"There is a cat outside\" farqi nimada?","options":["Farqi yo‘q","\"It’s raining\" hodisani bildiradi, \"There is a cat\" mushuk mavjudligini","\"There is\" faqat o‘tmishda ishlatiladi","\"It’s\" faqat ko‘plikda"],"correctIndex":1,"explanation":"Mavjudlik/joylashuv uchun \"There is/are\", ob-havo/vaqt/baho uchun \"It is\".","advice":"Kontekstga qarab \"There is\" yoki \"It is\" tanlang."},{"id":19,"skill":"There are (Ko‘plik)","question":"\"___ several English clubs at our university.\"","options":["There is","There are","There was","Is there"],"correctIndex":1,"explanation":"\"Several English clubs\" ko‘plik -> \"There are\".","advice":"Several, many, some + ko‘plik -> There are."},{"id":20,"skill":"Inkor shakli","question":"\"There ___ a bus at 7:00 AM on Sundays.\"","options":["isn’t","aren’t","weren’t","don’t"],"correctIndex":0,"explanation":"\"A bus\" birlik -> \"isn’t\".","advice":"Birlik inkorida \"isn’t\" ishlating."},{"id":21,"skill":"So‘roq shakli","question":"\"How many computers ___ in the lab?\"","options":["is there","are there","there are","there is"],"correctIndex":1,"explanation":"\"How many + ko‘plik ot + are there...?\"","advice":"\"How many\" dan keyin har doim ko‘plik ot keladi."},{"id":22,"skill":"O‘tgan zamon (There was / were)","question":"\"There ___ no internet connection an hour ago.\"","options":["was","were","are","is"],"correctIndex":0,"explanation":"\"Connection\" birlik + \"an hour ago\" -> \"was\".","advice":"Ago — o‘tgan zamon belgisi."},{"id":23,"skill":"There is (Birlik)","question":"\"___ a message for you.\"","options":["There is","There are","There were","Are there"],"correctIndex":0,"explanation":"\"A message\" birlik -> \"There is\".","advice":"Birlikda \"There is a...\"."},{"id":24,"skill":"There are (Ko‘plik)","question":"\"___ lots of new words in this unit.\"","options":["There is","There are","There was","Is there"],"correctIndex":1,"explanation":"\"Lots of new words\" ko‘plik -> \"There are\".","advice":"Lots of + ko‘plik -> There are."},{"id":25,"skill":"Inkor shakli","question":"\"There ___ any cafés open late at night.\"","options":["aren’t","isn’t","wasn’t","don’t"],"correctIndex":0,"explanation":"\"Cafés\" ko‘plik -> \"aren’t\".","advice":"Ko‘plik inkorida \"aren’t\"."},{"id":26,"skill":"So‘roq shakli","question":"\"Is there sugar in my tea?\"","options":["To‘g‘ri (sugar sanalmaydi, birlikda)","Noto‘g‘ri (are there bo‘lishi kerak)","Noto‘g‘ri (were there bo‘lishi kerak)","Faqat ko‘plikda to‘g‘ri"],"correctIndex":0,"explanation":"Sugar sanalmaydi, shuning uchun \"Is there sugar...?\" to‘g‘ri.","advice":"Sanalmaydigan otlar bilan \"Is there...?\" ishlating."},{"id":27,"skill":"O‘tgan zamon (There was / were)","question":"\"Were there many people at the seminar?\"","options":["To‘g‘ri (people ko‘plik + o‘tgan zamon)","Noto‘g‘ri (was there bo‘lishi kerak)","Noto‘g‘ri (is there bo‘lishi kerak)","Noto‘g‘ri"],"correctIndex":0,"explanation":"\"People\" ko‘plik ot bo‘lgani uchun \"Were there\" to‘g‘ri.","advice":"\"People\" ingliz tilida ko‘plik ot hisoblanadi."},{"id":28,"skill":"There is vs It is","question":"\"___ a great idea!\" (Bu ajoyib g‘oya!)","options":["It’s","There are","There were","Are there"],"correctIndex":0,"explanation":"Baho/fikr bildirganda \"It’s a great idea!\" deyiladi.","advice":"Fikr bildirishda \"It’s...\" ni to‘g‘ri ishlating."},{"id":29,"skill":"There are (Ko‘plik)","question":"\"___ different methods to learn English.\"","options":["There is","There are","There was","Was there"],"correctIndex":1,"explanation":"\"Different methods\" ko‘plik -> \"There are\".","advice":"Ko‘plik ot oldidan \"There are\"."},{"id":30,"skill":"Umumiy There is/are","question":"Qaysi jumla XATO?","options":["There is a cat.","There are two cats.","There is two cats.","There are many cats."],"correctIndex":2,"explanation":"\"Two cats\" ko‘plik bo‘lgani uchun \"There is two cats\" xato (\"There are two cats\" to‘g‘ri).","advice":"Otning birlik yoki ko‘plikligiga qarab \"is\" yoki \"are\" tanlang."}]',1795580034580);
INSERT INTO schedules (lesson_number,topic,level,location,starts_at,duration_min,explanation,vocab,links,questions,created_at) VALUES (5,'5-Mavzu: This, That, These, Those (Ko‘rsatish olmoshlari)','A1 – A2','B-bino, 204-xona',1795687200000,80,'1. YAQIN VA UZOQ, BIRLIK VA KO‘PLIK:
• THIS (bu — yaqin, birlik): "This is my phone."
• THAT (u / anavi — uzoq, birlik): "That is a tall building."
• THESE (bular — yaqin, ko‘plik): "These are my notes."
• THOSE (ular / anavilar — uzoq, ko‘plik): "Those are new students."

2. BIRLIKDAN KO‘PLIKKA O‘TKAZISH:
• This -> These | That -> Those
• is -> are | was -> were
• Misol: "This is a good book." -> "These are good books."
• Misol: "That was an interesting task." -> "Those were interesting tasks."','[]','[]','[{"id":1,"skill":"This (Yaqin birlik)","question":"\"___ is my new notebook in my hand.\"","options":["This","That","These","Those"],"correctIndex":0,"explanation":"Qo‘lda turgan (yaqin) bitta daftar -> \"This\".","advice":"Yaqin + birlik = This."},{"id":2,"skill":"That (Uzoq birlik)","question":"\"Look at ___ bird high in the sky!\"","options":["this","that","these","those"],"correctIndex":1,"explanation":"Osmondagi (uzoq) bitta qush -> \"that\".","advice":"Uzoq + birlik = That."},{"id":3,"skill":"These (Yaqin ko‘plik)","question":"\"___ are my friends standing right here.\"","options":["This","That","These","Those"],"correctIndex":2,"explanation":"Shu yerdagi (yaqin) ko‘p do‘stlar -> \"These\".","advice":"Yaqin + ko‘plik = These."},{"id":4,"skill":"Those (Uzoq ko‘plik)","question":"\"___ houses over there belong to our relatives.\"","options":["This","That","These","Those"],"correctIndex":3,"explanation":"Anavi yerdagi (uzoq) ko‘p uylar -> \"Those\".","advice":"Uzoq + ko‘plik = Those."},{"id":5,"skill":"Ko‘plikka aylantirish","question":"\"This is a student\" gapining ko‘plik shakli qaysi?","options":["That are students.","These are students.","Those is students.","This are students."],"correctIndex":1,"explanation":"This -> These, is -> are, a student -> students.","advice":"Ko‘plikka o‘tkazishda ko‘rsatish olmoshini ham, to be ni ham, otni ham o‘zgartiring."},{"id":6,"skill":"Ko‘plikka aylantirish","question":"\"That is a tall tree\" gapining ko‘plik shakli qaysi?","options":["These are tall trees.","Those are tall trees.","Those is tall trees.","That are tall trees."],"correctIndex":1,"explanation":"That -> Those, is -> are, a tall tree -> tall trees.","advice":"Uzoq + ko‘plik = Those are."},{"id":7,"skill":"Ko‘plikka aylantirish","question":"\"These are my keys\" gapining birlik shakli qaysi?","options":["This is my key.","That is my key.","This are my key.","These is my key."],"correctIndex":0,"explanation":"These -> This, are -> is, keys -> key.","advice":"Birlikka o‘tkazishda ko‘plik qo‘shimchasini olib tashlang."},{"id":8,"skill":"Ko‘plikka aylantirish","question":"\"Those were interesting lessons\" gapining birlik shakli qaysi?","options":["This was an interesting lesson.","That was an interesting lesson.","Those was an interesting lesson.","That were an interesting lesson."],"correctIndex":1,"explanation":"Those -> That, were -> was, lessons -> lesson.","advice":"O‘tgan zamon birlikda \"was\" ishlatiladi."},{"id":9,"skill":"Kontekst va masofa","question":"\"Can you pass me ___ book on the far table?\"","options":["this","that","these","those"],"correctIndex":1,"explanation":"\"Far table\" (uzoq stol) + \"book\" (birlik) -> \"that\".","advice":"Masofani bildiruvchi so‘zlarga (here/there, near/far) e’tibor bering."},{"id":10,"skill":"Kontekst va masofa","question":"\"I love ___ shoes I am wearing today.\"","options":["this","that","these","those"],"correctIndex":2,"explanation":"Kiyib turgan (yaqin) poyabzal (ko‘plik) -> \"these\".","advice":"Shoes juft/ko‘plik bo‘lgani uchun \"these\" yoki \"those\"."},{"id":11,"skill":"This / That / These / Those","question":"\"What is ___?\" (qo‘lingizdagi noma’lum narsani ko‘rsatib)","options":["this","these","those","they"],"correctIndex":0,"explanation":"Yaqin + birlik -> \"this\".","advice":"What is this? — foydali savol."},{"id":12,"skill":"This / That / These / Those","question":"\"What are ___?\" (uzoqda turgan ko‘p narsalarga ishora qilib)","options":["this","that","those","it"],"correctIndex":2,"explanation":"Uzoq + ko‘plik -> \"those\".","advice":"Ko‘plik savolida \"What are these/those?\" ishlatiladi."},{"id":13,"skill":"This / That / These / Those","question":"\"___ is a great idea!\" (suhbatdosh aytgan fikrga munosabat)","options":["That","These","Those","They"],"correctIndex":0,"explanation":"Aytilgan fikr/holatga ishora qilishda ko‘pincha \"That’s a great idea!\" deyiladi.","advice":"\"That’s a great idea!\" — jonli muloqot iborasi."},{"id":14,"skill":"Ko‘plikka aylantirish","question":"\"This apple is sweet.\" -> Ko‘plik shakli:","options":["These apples are sweet.","Those apples is sweet.","These apple are sweet.","This apples are sweet."],"correctIndex":0,"explanation":"This -> These, apple -> apples, is -> are.","advice":"Har bir qismni ko‘plikka moslang."},{"id":15,"skill":"Ko‘plikka aylantirish","question":"\"That car is fast.\" -> Ko‘plik shakli:","options":["Those cars are fast.","These car are fast.","Those car is fast.","That cars are fast."],"correctIndex":0,"explanation":"That -> Those, car -> cars, is -> are.","advice":"Those cars are fast."},{"id":16,"skill":"Kontekst va masofa","question":"\"___ exercises here are easy, but ___ over there are hard.\"","options":["These / those","This / that","Those / these","That / this"],"correctIndex":0,"explanation":"\"Here\" (yaqin) + ko‘plik = \"these\"; \"over there\" (uzoq) + ko‘plik = \"those\".","advice":"Yaqin-uzoq kontrastini to‘g‘ri juftlang."},{"id":17,"skill":"This / That / These / Those","question":"\"Hello, ___ is Sardor speaking.\" (telefonda o‘zini tanishtirish)","options":["this","that","these","those"],"correctIndex":0,"explanation":"Inglizcha telefon muloqotida o‘zini tanishtirishda \"This is...\" ishlatiladi.","advice":"\"This is [Name] speaking.\" — tabiiy telefon iborasi."},{"id":18,"skill":"This / That / These / Those","question":"\"Who is ___ man standing by the door?\"","options":["this","that","these","those"],"correctIndex":1,"explanation":"Eshik oldida turgan (biroz uzoqroq) bitta erkak -> \"that\".","advice":"Birlik odamga ishora qilishda \"this\" yoki \"that\"."},{"id":19,"skill":"Ko‘plikka aylantirish","question":"\"These are my notes.\" -> Birlik shakli:","options":["This is my note.","That are my note.","This are my notes.","These is my note."],"correctIndex":0,"explanation":"These -> This, are -> is, notes -> note.","advice":"Note — eslatma/konspekt."},{"id":20,"skill":"Ko‘plikka aylantirish","question":"\"Those are birds.\" -> Birlik shakli:","options":["That is a bird.","This is a bird.","Those is a bird.","That are a bird."],"correctIndex":0,"explanation":"Those -> That, are -> is, birds -> a bird.","advice":"Birlikda \"a/an\" artiklini unutmang."},{"id":21,"skill":"This / That / These / Those","question":"\"___ days, students learn fast with apps.\"","options":["These","This","That","Those"],"correctIndex":0,"explanation":"\"These days\" (hozirgi kunlarda) — ko‘plik va hozirgi davr ifodasi.","advice":"\"These days\" — ko‘p uchraydigan ibora."},{"id":22,"skill":"This / That / These / Those","question":"\"In ___ days, there were no smartphones.\"","options":["those","these","this","that"],"correctIndex":0,"explanation":"O‘tmishdagi o‘sha davrlar haqida gapirganda \"In those days\" deyiladi.","advice":"\"In those days\" — o‘tmish davrlari uchun."},{"id":23,"skill":"Kontekst va masofa","question":"Qaysi gap XATO yozilgan?","options":["This is my pen.","These are my pens.","This are my pens.","That is my bag."],"correctIndex":2,"explanation":"\"This\" birlikda, \"pens\" ko‘plikda — mos kelmaydi (\"These are my pens\" to‘g‘ri).","advice":"Ko‘rsatish olmoshi va otning sonini (birlik/ko‘plik) moslang."},{"id":24,"skill":"Kontekst va masofa","question":"Qaysi gap XATO yozilgan?","options":["Those are flowers.","That is a flower.","Those is a flower.","These are flowers."],"correctIndex":2,"explanation":"\"Those\" ko‘plikda, \"is a flower\" birlikda — mos kelmaydi.","advice":"\"Those are...\" bo‘lishi kerak."},{"id":25,"skill":"This / That / These / Those","question":"\"___ is my brother, Ali.\" (tanishtirish)","options":["This","These","Those","They"],"correctIndex":0,"explanation":"Bir kishini tanishtirishda \"This is...\" ishlatiladi.","advice":"This is + ism."},{"id":26,"skill":"This / That / These / Those","question":"\"___ are our new classmates.\" (bir nechta kishini tanishtirish)","options":["These","This","That","It"],"correctIndex":0,"explanation":"Bir nechta kishini tanishtirishda \"These are...\" ishlatiladi.","advice":"These are + ko‘plik."},{"id":27,"skill":"Ko‘plikka aylantirish","question":"\"This city is big.\" -> Ko‘plik:","options":["These cities are big.","Those city are big.","These citys are big.","This cities are big."],"correctIndex":0,"explanation":"City -> cities (-y -> -ies), this -> these, is -> are.","advice":"Cities imlosiga e’tibor bering."},{"id":28,"skill":"Ko‘plikka aylantirish","question":"\"That child is smart.\" -> Ko‘plik:","options":["Those children are smart.","These childs are smart.","Those childs are smart.","That children are smart."],"correctIndex":0,"explanation":"Child -> children (istisno ko‘plik!), that -> those, is -> are.","advice":"Child -> children istisno shaklini yodda tuting."},{"id":29,"skill":"This / That / These / Those","question":"\"I don’t like ___ kind of music.\"","options":["this","these","those","they"],"correctIndex":0,"explanation":"\"Kind\" birlikda -> \"this kind\" (yoki \"that kind\").","advice":"Birlik ot bilan \"this/that\"."},{"id":30,"skill":"Umumiy ko‘rsatish olmoshlari","question":"Jadvalni to‘g‘ri yakunlang: Yaqin-birlik (This), Yaqin-ko‘plik (These), Uzoq-birlik (That), Uzoq-ko‘plik (...)","options":["Those","This","These","It"],"correctIndex":0,"explanation":"Uzoq-ko‘plik = Those.","advice":"To‘rtlikni bitta jadvalda ko‘z oldingizga keltiring."}]',1795580034580);
INSERT INTO schedules (lesson_number,topic,level,location,starts_at,duration_min,explanation,vocab,links,questions,created_at) VALUES (6,'6-Mavzu: Takrorlash, o‘tilganlarni mustahkamlash va 5 ta mavzu asosida 50 ta test tahlili','A1 – A2 (Katta Takrorlash)','B-bino, 204-xona',1795854000000,120,'1. TAKRORLASH VA MUSTAHKAMLASH REJASI:
• 1-Mavzu: Harflar, raqamlar, harflar birikmalari, alifbo, so‘zlar, tovushlar va tarjima tartibi (Ega + Fe’l + To‘ldiruvchi + Joy + Vaqt).
• 2-Mavzu: "To be" (am/is/are) va "Was/Were" (o‘tgan zamon), inkor va so‘roq shakllari.
• 3-Mavzu: "Present Simple" (odatlar, faktlar, 3-shaxs -s/-es/-ies, do/does).
• 4-Mavzu: "There is / There are" va "There was / There were".
• 5-Mavzu: "This / That / These / Those" va birlik-ko‘plik o‘zgarishlari.

2. 50 TALIK KOMPLEKS TEST VA TAHLIL:
• Quyidagi testda barcha 5 ta mavzudan 10 tadan jami 50 ta savol jamlangan.
• Testni yakunlagach, har bir mavzu bo‘yicha o‘zlashtirish foizini (%), kuchli/zaif jihatlarni va amaliy tavsiyalarni ko‘rasiz!','[]','[]','[{"id":1,"skill":"1-Mavzu: Harflar, Raqamlar va Tarjima","question":"Ingliz alifbosida jami nechta harf bor?","options":["24 ta","26 ta","28 ta","30 ta"],"correctIndex":1,"explanation":"Ingliz alifbosida 26 ta harf mavjud (5-6 ta unli va qolgani undosh harflar).","advice":"Alifbodagi barcha 26 ta harfning nomini va talaffuzini yod oling."},{"id":2,"skill":"1-Mavzu: Harflar, Raqamlar va Tarjima","question":"Ingliz tilida klassik unli harflar qaysilar?","options":["A, E, I, O, U (va ba’zan Y)","A, O, U, I, E, Ə","B, C, D, F, G","A, E, I, O, W"],"correctIndex":0,"explanation":"Asosiy unli harflar A, E, I, O, U bo‘lib, Y ko‘pincha unli tovush beradi.","advice":"Unli harflarning qisqa va cho‘ziq tovushlarini farqlashni mashq qiling."},{"id":3,"skill":"1-Mavzu: Harflar, Raqamlar va Tarjima","question":"\"SH\" harflar birikmasi odatda qanday tovush beradi?","options":["/ʃ/ (\"sh\")","/tʃ/ (\"ch\")","/s/ (\"s\")","/ʒ/ (\"j\")"],"correctIndex":0,"explanation":"\"SH\" birikmasi o‘zbekcha \"sh\" ga yaqin /ʃ/ tovushini beradi: ship, she, shop.","advice":"\"SH\" (/ʃ/) va \"CH\" (/tʃ/) birikmalarini adashtirmang."},{"id":4,"skill":"1-Mavzu: Harflar, Raqamlar va Tarjima","question":"\"CH\" harflar birikmasi qaysi so‘zda /tʃ/ (\"ch\") o‘qiladi?","options":["School","Chair","Chemistry","Character"],"correctIndex":1,"explanation":"\"Chair\" so‘zida CH -> /tʃ/ o‘qiladi. (School, chemistry, characterda CH -> /k/ o‘qiladi).","advice":"\"CH\" birikmasi ko‘pincha /tʃ/, lekin yunoncha so‘zlarda /k/ bo‘lishini esda tuting."},{"id":5,"skill":"1-Mavzu: Harflar, Raqamlar va Tarjima","question":"\"PH\" harflar birikmasi qaysi tovushni beradi?","options":["/f/ (\"f\")","/p/ (\"p\")","/h/ (\"h\")","/v/ (\"v\")"],"correctIndex":0,"explanation":"\"PH\" birikmasi phone, photo, elephant so‘zlarida /f/ tovushini beradi.","advice":"\"PH\" ko‘rsangiz, darhol /f/ tovushini eslang."},{"id":6,"skill":"1-Mavzu: Harflar, Raqamlar va Tarjima","question":"\"TH\" birikmasining ikki asosiy tovushi qaysilar?","options":["/θ/ va /ð/","/t/ va /d/","/s/ va /z/","/f/ va /v/"],"correctIndex":0,"explanation":"\"TH\" jarangsiz /θ/ (think, three) va jarangli /ð/ (this, that, the) tovushlarini beradi.","advice":"Til uchini old tishlar orasiga qo‘yib /θ/ va /ð/ tovushlarini mashq qiling."},{"id":7,"skill":"1-Mavzu: Harflar, Raqamlar va Tarjima","question":"\"15\" soni inglizcha qanday yoziladi va aytiladi?","options":["Fifty","Fifteen","Fiveteen","Fiftin"],"correctIndex":1,"explanation":"15 — fifteen (/ˌfɪfˈtiːn/), 50 esa fifty (/ˈfɪfti/).","advice":"\"-teen\" (13–19) oxirgi bo‘g‘inga urg‘u beradi, \"-ty\" (20–90) birinchi bo‘g‘inga."},{"id":8,"skill":"1-Mavzu: Harflar, Raqamlar va Tarjima","question":"\"40\" sonining to‘g‘ri imlosi qaysi?","options":["Fourty","Forty","Fourteen","Forti"],"correctIndex":1,"explanation":"40 har doim \"forty\" deb yoziladi (\"u\" harfi tushib qoladi!).","advice":"\"Four\" (4) da \"u\" bor, lekin \"forty\" (40) da \"u\" yo‘q — imloga e’tibor bering."},{"id":9,"skill":"1-Mavzu: Harflar, Raqamlar va Tarjima","question":"\"12\" soni inglizcha qanday aytiladi?","options":["Twelf","Twelve","Twentieth","Two"],"correctIndex":1,"explanation":"12 — twelve (/twelv/).","advice":"1 dan 20 gacha bo‘lgan sonlarni yozma va og‘zaki pishiqlang."},{"id":10,"skill":"1-Mavzu: Harflar, Raqamlar va Tarjima","question":"\"100\" raqami inglizcha qanday ifodalanadi?","options":["One hundred","One thousand","Ten hundred","A hundredth"],"correctIndex":0,"explanation":"100 — one hundred (yoki a hundred).","advice":"Yuzlik, minglik sonlarni tuzish qoidasini takrorlang."},{"id":11,"skill":"2-Mavzu: To Be & Was / Were","question":"\"I ___ a first-year student.\" Bo‘sh o‘ringa nima qo‘yiladi?","options":["am","is","are","were"],"correctIndex":0,"explanation":"\"I\" olmoshidan keyin hozirgi zamonda \"am\" ishlatiladi.","advice":"\"I\" -> har doim \"am\" (yoki o‘tmishda \"was\")."},{"id":12,"skill":"2-Mavzu: To Be & Was / Were","question":"\"She ___ very kind and helpful.\"","options":["am","is","are","were"],"correctIndex":1,"explanation":"\"She\" (birlik, 3-shaxs) bilan hozirgi zamonda \"is\" qo‘llanadi.","advice":"He, she, it -> is."},{"id":13,"skill":"2-Mavzu: To Be & Was / Were","question":"\"They ___ in the classroom now.\"","options":["am","is","are","was"],"correctIndex":2,"explanation":"\"They\" (ko‘plik) bilan hozirgi zamonda \"are\" ishlatiladi.","advice":"We, you, they -> are."},{"id":14,"skill":"2-Mavzu: To Be & Was / Were","question":"\"Yesterday, I ___ at home all day.\"","options":["am","is","was","were"],"correctIndex":2,"explanation":"\"Yesterday\" o‘tgan zamonni bildiradi; \"I\" uchun o‘tgan zamon shakli \"was\".","advice":"O‘tgan zamon signal so‘zlariga (yesterday, last week, ago) e’tibor bering."},{"id":15,"skill":"2-Mavzu: To Be & Was / Were","question":"\"We ___ very happy after the lesson yesterday.\"","options":["was","were","are","am"],"correctIndex":1,"explanation":"\"We\" (ko‘plik) va \"yesterday\" (o‘tgan zamon) -> \"were\".","advice":"We, you, they (o‘tgan zamon) -> were."},{"id":16,"skill":"2-Mavzu: To Be & Was / Were","question":"\"He ___ tired last night.\"","options":["was","were","is","am"],"correctIndex":0,"explanation":"\"He\" va \"last night\" (o‘tgan zamon) -> \"was\".","advice":"I, he, she, it (o‘tgan zamon) -> was."},{"id":17,"skill":"2-Mavzu: To Be & Was / Were","question":"\"They ___ not late for the meeting.\" To‘g‘ri shaklni toping:","options":["is","are","was","am"],"correctIndex":1,"explanation":"Ko‘plikdagi \"They\" bilan hozirgi zamonda \"are not\" (aren’t) ishlatiladi.","advice":"Inkor gapda \"not\" to be shaklidan keyin qo‘yiladi."},{"id":18,"skill":"2-Mavzu: To Be & Was / Were","question":"\"___ you ready for the speaking club?\"","options":["Is","Am","Are","Was"],"correctIndex":2,"explanation":"\"You\" bilan hozirgi zamon so‘roq gapida \"Are\" gap boshiga chiqadi.","advice":"So‘roq gapda to be (am/is/are/was/were) egadan oldinga o‘tadi."},{"id":19,"skill":"2-Mavzu: To Be & Was / Were","question":"\"___ she at the library two hours ago?\"","options":["Is","Are","Was","Were"],"correctIndex":2,"explanation":"\"Two hours ago\" o‘tgan zamon; \"she\" uchun so‘roq boshida \"Was\" keladi.","advice":"O‘tgan zamon so‘roq gaplarida \"Was\" yoki \"Were\" ni tanlang."},{"id":20,"skill":"2-Mavzu: To Be & Was / Were","question":"\"It ___ cold last winter.\" (Inkor gap)","options":["wasn’t","weren’t","aren’t","isn’t"],"correctIndex":0,"explanation":"\"It\" va \"last winter\" -> o‘tgan zamon inkori \"wasn’t\" (was not).","advice":"Qisqa inkor shakllarni (isn’t, aren’t, wasn’t, weren’t) mashq qiling."},{"id":21,"skill":"3-Mavzu: Present Simple","question":"\"She ___ English every evening.\"","options":["study","studies","studying","studied"],"correctIndex":1,"explanation":"She (3-shaxs birlik) + undosh + Y -> \"ies\": studies.","advice":"Unli+Y -> -s (plays); undosh+Y -> -ies (studies)."},{"id":22,"skill":"3-Mavzu: Present Simple","question":"\"He ___ to work at 8 AM.\"","options":["go","goes","going","went"],"correctIndex":1,"explanation":"\"Go\" fe’li -o bilan tugagani uchun 3-shaxsda \"-es\" oladi: goes.","advice":"Oxiri -o, -ch, -sh, -ss, -x bilan tugasa \"-es\" qo‘shiladi."},{"id":23,"skill":"3-Mavzu: Present Simple","question":"\"I ___ drink coffee in the morning.\" (100% odat)","options":["always","never","rarely","hardly ever"],"correctIndex":0,"explanation":"\"Always\" (har doim) doimiy odatni bildiradi.","advice":"Always, usually, often, sometimes, never — Present Simple kalit so‘zlari."},{"id":24,"skill":"3-Mavzu: Present Simple","question":"\"They ___ live in Tashkent.\"","options":["don’t","doesn’t","isn’t","aren’t"],"correctIndex":0,"explanation":"Ko‘plikdagi \"They\" bilan inkor uchun \"don’t\" (do not) ishlatiladi.","advice":"I, we, you, they -> don’t."},{"id":25,"skill":"3-Mavzu: Present Simple","question":"\"He ___ like fast food.\"","options":["don’t","doesn’t","isn’t","aren’t"],"correctIndex":1,"explanation":"\"He\" bilan inkor uchun \"doesn’t\" ishlatiladi, asosiy fe’l esa \"-s\" siz yoziladi.","advice":"Doesn’t dan keyin fe’lga \"-s\" qo‘shmang: \"doesn’t like\" (likes emas!)."},{"id":26,"skill":"3-Mavzu: Present Simple","question":"\"___ you speak Uzbek and English?\"","options":["Do","Does","Are","Is"],"correctIndex":0,"explanation":"\"You\" bilan oddiy fe’l savolida \"Do\" ishlatiladi.","advice":"Oddiy fe’llarda (speak, go, work) savol yasash uchun \"Do/Does\" kerak."},{"id":27,"skill":"3-Mavzu: Present Simple","question":"\"___ your brother play chess?\"","options":["Do","Does","Is","Are"],"correctIndex":1,"explanation":"\"Your brother\" = \"He\" -> so‘roqda \"Does\" keladi.","advice":"Does + ega + V1 (asosiy shakldagi fe’l)."},{"id":28,"skill":"3-Mavzu: Present Simple","question":"\"The sun ___ in the east.\"","options":["rise","rises","rising","rose"],"correctIndex":1,"explanation":"Tabiat qonuni / umumiy haqiqat -> Present Simple; \"the sun\" birlik -> rises.","advice":"Ilmiy faktlar va tabiat hodisalari Present Simple da ifodalanadi."},{"id":29,"skill":"3-Mavzu: Present Simple","question":"Chastota ravishlari (always, usually, often) odatda gapda qayerda turadi?","options":["Asosiy fe’ldan oldin (lekin to be dan keyin)","Faqat gap oxirida","Faqat gap boshida","Artikldan oldin"],"correctIndex":0,"explanation":"\"I always wake up early.\" / \"She is always happy.\"","advice":"Fe’ldan oldin, to be (am/is/are) dan keyin qo‘ying."},{"id":30,"skill":"3-Mavzu: Present Simple","question":"\"My sister ___ watch TV on weekdays.\"","options":["don’t","doesn’t","not","no"],"correctIndex":1,"explanation":"\"My sister\" = \"She\" -> \"doesn’t watch\".","advice":"3-shaxs birlik inkorida \"doesn’t\" ishlatiladi."},{"id":31,"skill":"4-Mavzu: There is / There are","question":"\"___ a new student in our group.\"","options":["There is","There are","There were","Are there"],"correctIndex":0,"explanation":"\"A new student\" birlikda -> \"There is\".","advice":"Birlikdagi sanaladigan ot oldidan \"There is a/an...\" ishlatiladi."},{"id":32,"skill":"4-Mavzu: There is / There are","question":"\"___ many books on the shelf.\"","options":["There is","There are","There was","Is there"],"correctIndex":1,"explanation":"\"Many books\" ko‘plikda -> \"There are\".","advice":"Ko‘plikdagi otlar oldidan \"There are...\" qo‘llang."},{"id":33,"skill":"4-Mavzu: There is / There are","question":"\"There ___ any water in the bottle.\"","options":["isn’t","aren’t","weren’t","are"],"correctIndex":0,"explanation":"\"Water\" sanalmaydigan ot (birlik kabi) -> \"There isn’t\".","advice":"Sanalmaydigan otlar bilan \"There is / isn’t\" ishlatiladi."},{"id":34,"skill":"4-Mavzu: There is / There are","question":"\"There ___ any chairs in this room.\"","options":["isn’t","aren’t","is","was"],"correctIndex":1,"explanation":"\"Chairs\" ko‘plikda -> \"There aren’t\".","advice":"Ko‘plik inkorida ko‘pincha \"any\" ishlatiladi: \"aren’t any\"."},{"id":35,"skill":"4-Mavzu: There is / There are","question":"\"___ a park near your university?\"","options":["Is there","Are there","There is","There are"],"correctIndex":0,"explanation":"\"A park\" birlikda -> so‘roq \"Is there...?\"","advice":"Savolda \"is/are\" gap boshiga chiqadi."},{"id":36,"skill":"4-Mavzu: There is / There are","question":"\"___ any students in the hall?\"","options":["Is there","Are there","There are","There is"],"correctIndex":1,"explanation":"\"Students\" ko‘plikda -> so‘roq \"Are there...?\"","advice":"Ko‘plik savolida \"Are there any...?\" ishlatiladi."},{"id":37,"skill":"4-Mavzu: There is / There are","question":"\"Yesterday, ___ a big concert in the city.\"","options":["there is","there are","there was","there were"],"correctIndex":2,"explanation":"\"Yesterday\" + \"a big concert\" (birlik) -> \"there was\".","advice":"O‘tgan zamon birlik -> there was."},{"id":38,"skill":"4-Mavzu: There is / There are","question":"\"Last week, ___ ten participants in the club.\"","options":["there is","there are","there was","there were"],"correctIndex":3,"explanation":"\"Last week\" + \"ten participants\" (ko‘plik) -> \"there were\".","advice":"O‘tgan zamon ko‘plik -> there were."},{"id":39,"skill":"4-Mavzu: There is / There are","question":"\"There is a pen on the table\" o‘zbek tiliga qanday tarjima qilinadi?","options":["Stol ustida ruchka bor.","Ruchka stol ustida.","Men ruchkani ko‘ryapman.","Stol ruchka ustida."],"correctIndex":0,"explanation":"\"There is/are\" ko‘pincha \"bor / mavjud\" ma’nosini beradi.","advice":"Yangilik sifatida biror narsa qayerda borligini aytishda \"There is/are\" ishlating."},{"id":40,"skill":"4-Mavzu: There is / There are","question":"Qaysi gap TO‘G‘RI?","options":["There is a good book.","There is a good book on the desk.","There are a good book.","Is there a book are good?"],"correctIndex":1,"explanation":"\"There is + narsa + joy\" tuzilmasi tabiiy va to‘g‘ri.","advice":"Joy yoki mavjudlikni ko‘rsatishda \"There is/are\" ni to‘g‘ri qo‘llang."},{"id":41,"skill":"5-Mavzu: This / That / These / Those","question":"\"___ is my new notebook in my hand.\"","options":["This","That","These","Those"],"correctIndex":0,"explanation":"Qo‘lda turgan (yaqin) bitta daftar -> \"This\".","advice":"Yaqin + birlik = This."},{"id":42,"skill":"5-Mavzu: This / That / These / Those","question":"\"Look at ___ bird high in the sky!\"","options":["this","that","these","those"],"correctIndex":1,"explanation":"Osmondagi (uzoq) bitta qush -> \"that\".","advice":"Uzoq + birlik = That."},{"id":43,"skill":"5-Mavzu: This / That / These / Those","question":"\"___ are my friends standing right here.\"","options":["This","That","These","Those"],"correctIndex":2,"explanation":"Shu yerdagi (yaqin) ko‘p do‘stlar -> \"These\".","advice":"Yaqin + ko‘plik = These."},{"id":44,"skill":"5-Mavzu: This / That / These / Those","question":"\"___ houses over there belong to our relatives.\"","options":["This","That","These","Those"],"correctIndex":3,"explanation":"Anavi yerdagi (uzoq) ko‘p uylar -> \"Those\".","advice":"Uzoq + ko‘plik = Those."},{"id":45,"skill":"5-Mavzu: This / That / These / Those","question":"\"This is a student\" gapining ko‘plik shakli qaysi?","options":["That are students.","These are students.","Those is students.","This are students."],"correctIndex":1,"explanation":"This -> These, is -> are, a student -> students.","advice":"Ko‘plikka o‘tkazishda ko‘rsatish olmoshini ham, to be ni ham, otni ham o‘zgartiring."},{"id":46,"skill":"5-Mavzu: This / That / These / Those","question":"\"That is a tall tree\" gapining ko‘plik shakli qaysi?","options":["These are tall trees.","Those are tall trees.","Those is tall trees.","That are tall trees."],"correctIndex":1,"explanation":"That -> Those, is -> are, a tall tree -> tall trees.","advice":"Uzoq + ko‘plik = Those are."},{"id":47,"skill":"5-Mavzu: This / That / These / Those","question":"\"These are my keys\" gapining birlik shakli qaysi?","options":["This is my key.","That is my key.","This are my key.","These is my key."],"correctIndex":0,"explanation":"These -> This, are -> is, keys -> key.","advice":"Birlikka o‘tkazishda ko‘plik qo‘shimchasini olib tashlang."},{"id":48,"skill":"5-Mavzu: This / That / These / Those","question":"\"Those were interesting lessons\" gapining birlik shakli qaysi?","options":["This was an interesting lesson.","That was an interesting lesson.","Those was an interesting lesson.","That were an interesting lesson."],"correctIndex":1,"explanation":"Those -> That, were -> was, lessons -> lesson.","advice":"O‘tgan zamon birlikda \"was\" ishlatiladi."},{"id":49,"skill":"5-Mavzu: This / That / These / Those","question":"\"Can you pass me ___ book on the far table?\"","options":["this","that","these","those"],"correctIndex":1,"explanation":"\"Far table\" (uzoq stol) + \"book\" (birlik) -> \"that\".","advice":"Masofani bildiruvchi so‘zlarga (here/there, near/far) e’tibor bering."},{"id":50,"skill":"5-Mavzu: This / That / These / Those","question":"\"I love ___ shoes I am wearing today.\"","options":["this","that","these","those"],"correctIndex":2,"explanation":"Kiyib turgan (yaqin) poyabzal (ko‘plik) -> \"these\".","advice":"Shoes juft/ko‘plik bo‘lgani uchun \"these\" yoki \"those\"."}]',1795580034580);
